9	  const DEFAULT_PDS_URL = 'https://obsign.org';
10	
11	  let { onnext, onback = undefined }: { onnext: () => void; onback?: () => void } = $props();
12	
13	  let url = $state(DEFAULT_PDS_URL);
14	  let loading = $state(false);
15	  let error = $state<string | undefined>(undefined);
16	
17	  // Seed the field from the currently-saved PDS URL (if any) so the user sees the host that is
18	  // actually active, instead of always seeing the built-in default. The active URL is restored
19	  // from the Keychain at launch and is otherwise invisible — which made a stale/wrong host
20	  // (e.g. a previous staging URL) impossible to notice.
21	  onMount(() => {
22	    const initialUrl = url;
23	    void (async () => {
24	      try {
25	        const saved = await getPdsUrl();
26	        // Only hydrate if the user hasn't started editing while the IPC call was in flight,
27	        // otherwise a late resolve would clobber their input.
28	        if (saved && url === initialUrl) url = saved;
29	      } catch (e) {
30	        console.warn('[PdsConfigScreen] failed to load saved PDS URL:', e);
31	      }
32	    })();
33	  });
34	
35	  let isValidFormat = $derived(
36	    url.trim().length > 0 &&
37	      (url.startsWith('http://') || url.startsWith('https://'))
38	  );
39	
40	  async function handleConnect() {
41	    error = undefined;
42	    loading = true;
43	    try {
44	      await savePdsUrl(url.trim());
45	      onnext();
46	    } catch (e) {
47	      const err = e as PdsConfigError;
48	      if (err.code === 'INVALID_URL') {
49	        error = 'Invalid URL — must start with http:// or https://';
50	      } else if (err.code === 'KEYCHAIN_ERROR') {
51	        error = 'Could not save the server URL. Please try again.';
52	      } else {
53	        error = 'Could not reach the server. Check the URL and try again.';
54	      }
55	    } finally {
56	      loading = false;
57	    }
58	  }
59	</script>
