    let resp = state
        .custos_client()
        .get("/xrpc/com.atproto.server.describeServer")
        .await
        .map_err(|e| e.to_string())?;

    if !resp.status().is_success() {
        return Err(format!(
            "describeServer returned HTTP {}",
            resp.status().as_u16()
        ));
    }

    resp.json()
        .await
        .map_err(|e| format!("failed to parse describeServer response: {e}"))
}

